<?php
function purchase_pricing_fields(array $p,array $input): void {
    $base=$p['_purchase_original']??$p['_base_product']??$p;$s=$p['_purchase_pricing']??null;$term=(int)($input['prepay_months']??1);$reward=(int)($input['reward_id']??0); ?>
<section class="package-config" data-purchase-pricing><h3>Abrechnungszeitraum & Gutschein</h3>
<?php if($base['billing']==='month' && empty($base['_quote_id']) && empty($p['_module_intent'])):$terms=prepayment_options((int)$base['id']);if($terms): ?><label class="field"><span>Vorauszahlung / Verlängerungszeitraum</span><select name="prepay_months"><option value="1">Monatlich</option><?php foreach($terms as $t): ?><option value="<?= (int)$t['months'] ?>" <?= $term===(int)$t['months']?'selected':'' ?>><?= (int)$t['months'] ?> Monate<?= $t['discount_bps']?' · '.number_format($t['discount_bps']/100,2,',','.').' % Rabatt':'' ?><?= (int)$t['months']===24?' · Rechnung mit PayPal-Link':'' ?></option><?php endforeach ?></select></label><?php endif;endif ?>
<label class="field"><span>Gutscheincode (optional)</span><input name="coupon_code" value="<?= e($input['coupon_code']??'') ?>" maxlength="64" autocomplete="off" placeholder="Code bei jeder Bestellung neu eingeben"><small>Nur ein Code je Bestellung. Persönliche Gutscheine sind an dein Konto gebunden.</small></label>
<?php $rewards=empty($p['_module_intent'])?all("SELECT r.*,o.product_name FROM shop_coupon_rewards r JOIN shop_orders o ON o.id=r.source_order_id WHERE r.customer_id=? AND r.state='available' AND r.category=? ORDER BY r.id",[user()['id'],$base['category']]):[];if($rewards): ?><label class="field"><span>Zusatzpaket-Bonus statt Gutscheincode</span><select name="reward_id"><option value="0">Keinen Bonus verwenden</option><?php foreach($rewards as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $reward===(int)$r['id']?'selected':'' ?>><?= e($r['product_name']) ?> · bis <?= money(vat_from_net((int)$r['cap_net_cents'])['gross_cents']) ?> inkl. MwSt. im ersten Zeitraum</option><?php endforeach ?></select></label><?php endif ?>
<button class="button button-outline" type="submit" name="action" value="pricing_preview" formnovalidate>Auswahl & Rabatt prüfen</button><p class="small" data-pricing-stale role="status" hidden>Deine Auswahl wurde geändert. Bitte prüfe den Preis erneut, bevor du bestellst.</p>
<?php if($s): ?><dl class="detail-list"><div><dt>Listenpreis netto für <?= billing_months($p['billing'])?:1 ?> <?= billing_months($p['billing'])?'Monat(e)':'Leistung' ?></dt><dd><?= money($s['original_net']) ?></dd></div><div><dt>Vorauszahlungsrabatt netto</dt><dd>− <?= money($s['original_net']-$s['term_net']) ?></dd></div><div><dt><?= $s['reward_id']?'Zusatzpaket-Bonus':'Gutscheinrabatt' ?> netto</dt><dd>− <?= money($s['discount_net']) ?></dd></div><div><dt>Jetzt inkl. 19 % MwSt.</dt><dd><strong><?= price($p) ?></strong></dd></div><div><dt>Danach je <?= cycle($p['billing']) ?> inkl. 19 % MwSt.</dt><dd><?= money(pricing_cart_regular_gross($p)) ?></dd></div></dl><p class="small"><?= $s['test_only']?'Persönlicher Test: Dieses Paket bleibt kostenlos. Es wird keine PayPal-Zahlung angelegt. Kostenpflichtige Domainregistrierungen werden mit dem Testcode nicht ausgelöst.':($s['invoice_renewal']?'Verlängerung nach 24 Monaten mit neuer Rechnung und PayPal-Zahlungslink.':'Ein Rabatt für den ersten Zeitraum endet danach. Für folgende Zahlungen bestätigst du das PayPal-Abo.') ?></p><?php endif ?>
<?php if($s && isset($p['_base_product']) && billing_months($p['billing']) && ($s['initial_net'] || $s['regular_net'])):$lines=array_values(array_filter($p['_module_selection']??[],fn($l)=>empty($l['included']) && (int)$l['net_cents']>0));if($lines):[$basePart,$parts]=pricing_split_cart($p,module_checkout_base($p),$lines); ?><p class="small"><strong>Getrennte Verträge:</strong> Du bestellst jetzt das Grundpaket für <?= price($basePart) ?> inkl. MwSt.; danach <?= money(vat_from_net((int)$basePart['_purchase_pricing']['regular_net'])['gross_cents']) ?> / <?= cycle($p['billing']) ?>. Die ausgewählten Zusatzmodule gibst du anschließend einzeln in der Bestellübersicht frei. Der oben ausgewiesene Gesamtpreis enthält bereits alle ausgewählten Module und Rabatte. Jedes Modul bleibt separat kündbar.</p><?php endif;endif ?>
</section><?php
}
function purchase_order_details(array $order): void {
    $s=pricing_snapshot($order);if(!$s)return;echo '<div class="info-box"><span><strong>'.e($s['coupon']['name']??($s['reward_id']?'Kostenloses Zusatzpaket':'Vorauszahlung')).'</strong><br>Erster Zeitraum: '.money(vat_from_net((int)$s['initial_net'])['gross_cents']).' inkl. MwSt.; danach '.money(vat_from_net((int)$s['regular_net'])['gross_cents']).' / '.e(cycle($order['billing'])).'. '.($s['test_only']?'Persönlicher Test ohne Geldfluss.':($s['invoice_renewal']?'Rechnung mit PayPal-Link alle 24 Monate.':'')).'</span></div>';
}
